targets.expr:
avg by (user_unit) (
  last_over_time(
    {user_unit="coinbase-trader-ws.service"} 
    |= "[Performance]"
    | regexp `\| PnL: \$(?P<pnl_str>[-+]?[0-9,.]+)`
    | line_format `{{ .pnl_str | replace "," "" }}`
    | regexp `(?P<pnl>[-+]?[0-9.]+)`
    | unwrap pnl [1h]
  )
)

sum by (executor) (
  last_over_time(
    {user_unit="coinbase-trader-ws.service"} 
    | regexp `\[(?P<executor>[^\]]+)\] Sub-Portfolio Value: \$(?P<balance_str>[0-9,.]+)`
    | line_format `{{ .balance_str | replace "," "" }}`
    | regexp `(?P<balance>[0-9.]+)`
    | drop balance_str
    | unwrap balance [5m]
  )
)

sum(
  last_over_time(
    {user_unit="coinbase-trader-ws.service"} 
    | regexp `INFO - Portfolio Value: \$(?P<balance_str>[0-9,.]+)`
    | line_format `{{ .balance_str | replace "," "" }}`
    | regexp `(?P<balance>[0-9.]+)`
    | drop balance_str
    | unwrap balance [5m]
  )
)

sum by (user_unit) (
  last_over_time(
    {user_unit="coinbase-trader-ws.service"} 
    | regexp `fees=\$(?P<fee_str>[0-9,.]+)`
    | line_format `{{ .fee_str | replace "," "" }}`
    | regexp `(?P<fee>[0-9.]+)`
    | unwrap fee [1h]
  )
)
